import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import http from 'node:http';
import vm from 'node:vm';
import {createRequire} from 'node:module';
const require=createRequire(import.meta.url);
// Use code generated by npm run build:main; this works across TypeScript compiler versions.
const compiledUrl=new URL('../dist/google-drive.js',import.meta.url);
if(!fs.existsSync(compiledUrl)){
  throw new Error('Chua co dist/google-drive.js. Hay chay npm run build:main truoc khi test.');
}
const compiled=fs.readFileSync(compiledUrl,'utf8');
function harness(mode='success'){
 const folder=fs.mkdtempSync(path.join(os.tmpdir(),'amorri-oauth-'));
 let browserPage='';
 const safeStorage={
   isEncryptionAvailable:()=>true,
   encryptString:s=>Buffer.from('dpapi-mock:'+s),
   decryptString:b=>{const s=b.toString();if(!s.startsWith('dpapi-mock:'))throw new Error('invalid DPAPI');return s.slice(11);}
 };
 const mockElectron={app:{getPath:(name)=>{assert.equal(name,'userData');return folder;}},safeStorage,
   shell:{openExternal:async url=>{
      const auth=new URL(url);
      const callback=new URL(auth.searchParams.get('redirect_uri'));
      callback.searchParams.set('code','mock-code');
      callback.searchParams.set('state',auth.searchParams.get('state'));
      const r=await new Promise((resolve,reject)=>{
        http.get(callback,res=>{
          let body='';res.on('data',d=>body+=d);res.on('end',()=>resolve({status:res.statusCode,body}));
        }).on('error',reject);
      });
      browserPage=r;
   }} };
 const fakeFetch=async(url,options={})=>{
   const u=String(url);
   if(u.includes('/token')){
     const params=new URLSearchParams(options.body);
     assert.equal(params.get('client_id'),'example.apps.googleusercontent.com');
     assert.ok(params.get('code_verifier'));
     if(mode==='missing-secret'&&!params.get('client_secret'))
       return new Response(JSON.stringify({error:'invalid_request',error_description:'client_secret is missing'}),{status:400});
     return new Response(JSON.stringify({access_token:'mock-token',refresh_token:'mock-refresh',expires_in:3600}),{status:200});
   }
   if(u.includes('/about?fields=')){
     assert.equal(options.headers.Authorization,'Bearer mock-token');
     if(mode==='drive-403')return new Response(JSON.stringify({message:'Drive disabled'}),{status:403});
     return new Response(JSON.stringify({user:{emailAddress:'drive-b@gmail.com'}}),{status:200});
   }
   throw new Error('Unknown URL');
 };
 // TypeScript has already been compiled by the project's own tsconfig.
 const mod={exports:{}};
 vm.runInNewContext(compiled,{module:mod,exports:mod.exports,require:id=>id==='electron'?mockElectron:require(id),
   fetch:fakeFetch,URL,URLSearchParams,Buffer,Response,Promise,Date,setTimeout,clearTimeout,process},
  {filename:'google-drive.js'});
 return {api:mod.exports,folder,get page(){return browserPage;}, cleanup(){fs.rmSync(folder,{recursive:true,force:true});}};
}
test('Only reports success after token exchange, Drive verification and DPAPI persistence',async()=>{
 const x=harness();try{
  x.api.configureDriveOAuth('example.apps.googleusercontent.com','GOCSPX-test');
  const r=await x.api.connectGoogleDrive();
  assert.equal(r.email,'drive-b@gmail.com');
  assert.equal(await x.api.driveAccountEmail(),'drive-b@gmail.com');
  assert.equal(x.page.status,200);
  assert.match(x.page.body,/Kết nối Google Drive thành công/);
  const raw=fs.readFileSync(path.join(x.folder,'google-drive-token.dpapi'),'utf8');
  assert.ok(raw.startsWith('dpapi-mock:')); // mock only; Windows uses actual DPAPI
 }finally{x.cleanup();}
});
test('Missing Google client secret fails without false success and never persists a token',async()=>{
 const x=harness('missing-secret');try{
  x.api.configureDriveOAuth('example.apps.googleusercontent.com');
  await assert.rejects(x.api.connectGoogleDrive(),/client_secret is missing/);
  await new Promise(resolve=>setTimeout(resolve,15));
  assert.equal(x.page.status,502);
  assert.match(x.page.body,/Chưa kết nối được Google Drive/);
  assert.ok(!fs.existsSync(path.join(x.folder,'google-drive-token.dpapi')));
 }finally{x.cleanup();}
});
test('Drive API 403 after token exchange does not claim success',async()=>{
 const x=harness('drive-403');try{
  x.api.configureDriveOAuth('example.apps.googleusercontent.com','GOCSPX-test');
  await assert.rejects(x.api.connectGoogleDrive(),/HTTP 403/);
  await new Promise(resolve=>setTimeout(resolve,15));
  assert.equal(x.page.status,502);
  assert.ok(!fs.existsSync(path.join(x.folder,'google-drive-token.dpapi')));
 }finally{x.cleanup();}
});
